import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"文公易说","description":"文公易说 - 文公易说","frontmatter":{"title":"文公易说","description":"文公易说 - 文公易说"},"headers":[],"relativePath":"zh/classics/wengong-zhu/001.md","filePath":"zh/classics/wengong-zhu/001.md"}'),l={name:"zh/classics/wengong-zhu/001.md"};function o(c,a,i,d,p,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"文公易说",tabindex:"-1"},[r("文公易说 "),e("a",{class:"header-anchor",href:"#文公易说","aria-label":"Permalink to “文公易说”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：朱文公易说二十二卷，宋朱鉴编。案朱子世系，朱子三子，长曰塾。塾二子，长曰鉴，则朱子嫡长孙也。鉴字子明，以荫补迪功郎，官至湖广总领。朱子注易之书，为目有五：曰易传十一卷，曰易本义十二卷，曰易学启蒙三卷，曰古易音训二卷，曰蓍卦考误。一巷皆有成帙。其朋友论难与及门之辨说，则散见语录中。鉴汇而葺之，以成是编。昔郑元笺注诸经，其孙魏侍中小同复裒其门人问答之词，为郑志十一巷。鉴之编辑绪言，亦犹此例也。考朱子初作易传，用王弼本，后作易本义，始用吕祖谦本。易传，宋志著录，今已散佚。当理宗以后，朱子之学大行，剩语残编，无不奉为球璧，不应手成巨帙，反至无传。殆以未定之说，自削其稿，故不复流布与？鉴是书全采语录之文，以补本义之阙。其中或门人记述，未必尽合师说，或偶然问答，未必勒为确论。安知无如易传之类，为朱子所欲刊除者？然收拾放佚，以备考证，亦可云能世其家学矣。乾隆四十二年二月恭校上。",-1),e("p",null,"总纂官 臣 纪呁、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。",-1)])])}const _=t(l,[["render",o]]);export{m as __pageData,_ as default};
